{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "[18F]MPPF, a 4-[18F]fluorobenzoyl-containing radiotracer, is a P-gp substrate with only 0.05% ID/g brain uptake in rats, directly demonstrating that this acyl piperazine/amine scaffold has efflux-limited poor CNS access; this transfers strongly to the query's 4-[18F]fluorobenzoyl piperazine amide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "β-(4-[18F]fluorobenzoyl)propionic acid showed negligible rat brain uptake after injection, indicating that the 4-[18F]fluorobenzoyl acyl motif itself does not confer brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A [123I]benzyl piperazine amide SPECT tracer showed no brain localization in mice, supporting that piperazine amide radiotracers with bulky aromatic substituents fail to cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A close [18F]fluoro analogue was an efflux substrate at the rodent BBB, with low baseline brain uptake that increased after transporter inhibition; the query's similar amide/piperazine radiotracer is likely also efflux-limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Reversible MAGL tracers with amide/piperazine architecture were peripherally restricted with low brain accumulation in rodents; the query's indazolone-acetamide piperazine structure is in the same class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ELN441958, a piperazine-containing amide, had brain AUC only 6.7% of plasma in mice, a direct low-permeability measurement consistent with the query's expected phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A piperazine amide PET radioligand reached only 0.7% ID peak brain radioactivity in monkey, attributed to P-gp efflux, reinforcing poor CNS access for this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Fail: multiple high-transfer in vivo measurements on structurally related 4-[18F]fluorobenzoyl piperazine amide radiotracers show negligible-to-low brain uptake, low brain/plasma ratios, and P-gp/BCRP efflux; no credible evidence of meaningful CNS access for the query.",
  "evidence_gaps": [
    "No direct experimental measurement on the exact query molecule",
    "No transporter-inhibition or CSF data for the query",
    "No human data for the query",
    "No dose-response or time-course data for the query"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

